insert into public.blog_posts (slug,title,excerpt,body,category,status,event_date,location,incident_number,rescue_type,source_url,published_at) values
('beardown-tor','Assisting an unwell walker','A search near Beardown Tors after a walker became unwell. The team’s doctor later checked the walker at Beardown Farm.','Police requested help at 15:30. Volunteers deployed from Holming Beam while a rescue vehicle approached through Beardown Farm. After searches began, telephone contact confirmed the walker had recovered enough to return towards the farm with another walker. A team doctor met and assessed them there. The team stood down at 17:00.','Rescue','published','2026-09-16','Beardown Tor','31','Medical assistance','https://dsrt-tavistock.org.uk/2026/09/17/16-09-2026-unwell-walker-beardown-tor/','2026-09-16T12:00:00Z'),
('leather-tor','Helping a fallen walker to safety','Volunteers worked alongside ambulance clinicians to help an injured walker from the rocks near Leather Tor to a waiting ambulance.','The team was called at 12:29 after a walker fell and injured their hip. The first rescuers arrived at 13:07, followed by a stretcher team. A team vehicle brought ambulance clinicians close to the casualty. Following assessment and treatment, volunteers carried the walker to the road. Rescue vehicles returned to base at 14:30.','Rescue','published','2026-08-23','Leather Tor','30','Casualty evacuation','https://dsrt-tavistock.org.uk/2026/08/23/23-08-2026-fallen-walker-near-leather-tor/','2026-08-23T12:00:00Z'),
('foggintor','A helping hand at Foggintor','A foot team and rescue vehicle assisted a person who had been injured while scrambling near the quarry.','The ambulance service requested support after an injury left a person struggling to walk. Volunteers reached and assessed the casualty, then used a team vehicle to bring them to the waiting ambulance for onward care at Derriford Hospital.','Rescue','published','2026-08-18','Foggintor Quarry','29','Casualty evacuation','https://dsrt-tavistock.org.uk/2026/08/23/18-08-2026-injured-male-foggintor/','2026-08-18T12:00:00Z'),
('yennadon','Supporting an injured horse rider','A stretcher evacuation on Yennadon Down helped ambulance clinicians bring an injured rider off the moor.','Called at 12:05, the team assisted South Western Ambulance Service with a rider who had fallen above Burrator Reservoir. Volunteers helped immobilise and carry the casualty down to an ambulance. The team stood down at 13:10.','Rescue','published','2026-08-09','Yennadon Down','28','Casualty evacuation','https://dsrt-tavistock.org.uk/2026/08/10/09-08-2026-fallen-horserider-yennadon/','2026-08-09T12:00:00Z')
